// Table layout.
//
// Tables earn a formatting context of their own here rather than being
// approximated with flex, because the thing a table does that nothing else
// does is **size a column from every cell in it** — a constraint that runs
// across the grain of the box tree, and the reason a table cannot be
// expressed as nested rows of boxes without measuring twice and guessing.
//
// The documents this component exists for are full of them: exported
// reports, mail, anything generated by a template. So the auto algorithm is
// implemented rather than stubbed, and `table-layout: fixed` is implemented
// beside it because that is the one an author reaches for when the auto
// algorithm is too slow — which, on a table with a thousand rows, it is.
import { AUTO, isPct, resolveOrNull } from '../css/values.js';
import type { Len } from '../css/values.js';
import type { ComputedStyle } from '../css/style.js';
import { Box, CLIPPED_CELLS, COLLAPSED_CELLS, isBlank } from './boxes.js';
import {
  CELL_CONTENT,
  FLEXED_HEIGHT,
  MIN_CONTENT_PROBE,
  STRETCHED_ACROSS,
  USED_HEIGHT,
  clampHeight,
  cyclicWidth,
  exactMinContent,
  layoutBlockIn,
  measureIntrinsicWidth,
  moveContent,
  moveTo,
  resolveEdges,
} from './block.js';
import type { LayoutContext } from './block.js';
import { firstBaselineIn } from './inline.js';
import { tableGrid } from './grid.js';
import type { Cell } from './grid.js';

/** Lay out a table's insides. Returns the content height. */
export function layoutTable(
  table: Box,
  ctx: LayoutContext,
  contentWidth: number,
): number {
  const { rows, captions, cells, columnCount, columnBoxes, columnGroups } =
    tableGrid(table);
  table.captionTop = 0;
  table.captionBottom = 0;
  // a percentage of a width that is not known is `auto`: the table is as
  // wide as its columns where its content is measured (`cyclicWidth`)
  const own =
    table.style.width === AUTO || cyclicWidth(table.style, contentWidth);
  // — and one a grid stretches across its area is as wide as that, as a
  // table with a width of its own is (`STRETCHED_ACROSS`)
  const auto = own && !STRETCHED_ACROSS.has(table);
  if (!columnCount) {
    // With no columns, an auto table is as wide as its widest caption can
    // be and its `min-width` asks, as one with columns is at the least
    // (17.5.2), rather than as the room on offer: a caption over no cells
    // was centred in the width of the page.
    if (auto) {
      let inner = captions.length
        ? captionMinimum(captions, ctx) - table.horizontalExtra
        : 0;
      const min = resolveOrNull(table.style.minWidth, contentWidth);
      if (min !== null) {
        inner = Math.max(
          inner,
          table.style.boxSizing === 'border-box'
            ? min - table.horizontalExtra
            : min,
        );
      }
      table.width = Math.max(0, inner) + table.horizontalExtra;
    }
    layoutCaptions(captions, ctx, table);
    TABLE_CONTENT.set(
      table,
      table.captionTop + table.captionBottom + table.verticalExtra,
    );
    return 0;
  }

  const style = table.style;
  // between the columns, and between the rows (CSS 2.1 17.6.1)
  const apart = style.borderCollapse !== 'collapse';
  const spacing = apart ? style.borderSpacing : 0;
  const rowSpacing = apart ? style.borderSpacingY : 0;
  const gaps = spacing * (columnCount + 1);
  const available = Math.max(0, contentWidth - gaps);

  // While the columns are sized, a percentage in a cell's padding is of
  // nothing: the width it is of is the one the columns are being sized to
  // come to (CSS Sizing 3, 5.2.1), and a cell asks of its column what its
  // content does. It is a share of the row once the columns have their
  // widths, below. Taken of the table's width here, and of the cell's own
  // where the cell was laid out, a padded cell's column was wider than
  // its share and its padding narrower.
  for (const cell of cells) resolveEdges(cell.box, 0);

  // a fixed layout needs a width to be fixed to; with `auto` a table is laid
  // out by its contents after all (CSS 2.1 17.5.2.1), stretched or not
  const fixed = style.tableLayout === 'fixed' && !own;
  // a percentage of the table's width less its spacing (CSS 2.1 17.5.2.1)
  const set = columnWidths(columnBoxes, columnGroups, available, fixed);
  const widths = fixed
    ? fixedColumns(cells, set, columnCount, available, spacing)
    : autoColumns(
        cells,
        set,
        columnLeast(columnBoxes, columnGroups),
        columnCount,
        available,
        ctx,
        contentWidth,
        !auto,
        spacing,
      );

  // --- place ---------------------------------------------------------------
  // An auto table is at least as wide as its widest caption can be (CSS 2.1
  // 17.5.2), and as its `min-width` asks; the columns share what that adds.
  if (auto) {
    let room = 0;
    if (captions.length) {
      room = captionMinimum(captions, ctx) - table.horizontalExtra - gaps;
    }
    const min = resolveOrNull(style.minWidth, contentWidth);
    if (min !== null) {
      const inner =
        style.boxSizing === 'border-box' ? min - table.horizontalExtra : min;
      room = Math.max(room, inner - gaps);
    }
    const sum = widths.reduce((a, b) => a + b, 0);
    if (room > sum) {
      for (let c = 0; c < columnCount; c += 1) {
        widths[c] +=
          sum > 0
            ? (widths[c] / sum) * (room - sum)
            : (room - sum) / columnCount;
      }
    }
  }

  // A column that `visibility: collapse` takes out of the table has been
  // sized with the rest, and is no room at all where they are placed (CSS
  // 2.1 17.5.5): no width, and no spacing after it. Its cells are still
  // laid out at the width they would have had, so that taking it out
  // changes no row's height.
  const columnX: number[] = new Array<number>(columnCount);
  const gone: boolean[] = new Array<boolean>(columnCount);
  let anyGone = false;
  let x = table.contentX + spacing;
  for (let c = 0; c < columnCount; c += 1) {
    columnX[c] = x;
    gone[c] = collapsedColumn(columnBoxes[c], columnGroups[c]);
    if (gone[c]) anyGone = true;
    else x += widths[c] + spacing;
  }
  // A table with `width: auto` is as wide as its columns need, not as wide as
  // its container — it shrinks to fit, which is what makes a two-column table
  // in a wide document a small table rather than a pair of columns stranded
  // at the left of a full-width box. The columns were sized against the space
  // on offer, so this narrows it — but never past the least its columns can
  // be (CSS 2.1 17.5.2.2): a table whose words do not fit is wider than the
  // room, as a word is, and one beside a float goes below it.
  //
  // A table set to a width is as wide as it or its columns, whichever is the
  // wider: columns set wider than the table widen it. A column taken out
  // gives its room back either way, set width or not.
  const used = x - table.contentX;
  let tableContentWidth = contentWidth;
  if (auto) {
    tableContentWidth = used;
    table.width = tableContentWidth + table.horizontalExtra;
  } else if (used > contentWidth || anyGone) {
    tableContentWidth = used;
    table.width = used + table.horizontalExtra;
  }
  layoutCaptions(captions, ctx, table);

  const top = table.contentY + table.captionTop;
  let y = top;
  const rowTop: number[] = new Array<number>(rows.length);
  const rowHeight: number[] = new Array<number>(rows.length).fill(0);
  y += rowSpacing;

  // Size every cell at its column width first, so a row's height is the
  // tallest cell in it rather than the first one that was measured. What
  // its content came to is kept apart from a height the cell sets: it is
  // that content `vertical-align` moves in the cell.
  //
  // A percentage in a cell's padding is of the width of its row: the
  // columns and the spacing between them, without the spacing either side
  // and the table's own padding. CSS 2.1 8.4 has it of the containing
  // block's width and names none for a cell; the row's is what browsers
  // take, and what the table's content box is wherever there is no
  // spacing. Every column counts, one `visibility: collapse` takes out
  // too, so that taking it out changes no row's height.
  let rowWidth = spacing * Math.max(0, columnCount - 1);
  for (const columnWidth of widths) rowWidth += columnWidth;
  const natural: number[] = new Array<number>(cells.length);
  for (let i = 0; i < cells.length; i += 1) {
    const cell = cells[i];
    const width = spannedWidth(widths, cell, spacing);
    ctx.layoutSubtree(cell.box, width, rowWidth);
    natural[i] = CELL_CONTENT.get(cell.box) ?? cell.box.height;
    // A height a cell sets is a least one: its content is laid out as a
    // block's, which keeps a height it sets and lets the content run out of
    // it, and a cell does not. `<td height="10">` with a line in it is as
    // tall as the line (CSS 2.1 17.5.3), where it was 10px with the line
    // hanging out of it.
    if (natural[i] > cell.box.height) cell.box.height = natural[i];
    const specified = resolveOrNull(cell.box.style.height, NaN);
    if (specified !== null) {
      cell.box.height = Math.max(
        cell.box.height,
        specified + cell.box.verticalExtra,
      );
    }
  }
  // A cell aligned on the baseline — every value but `top`, `middle` and
  // `bottom` — hangs its first line on its first row's baseline, the lowest
  // of theirs from the row's top (CSS 2.1 17.5.3), and the row is as tall as
  // the cells hung from it need. What moves down is the content, so a cell
  // needs the lift and its content, and a height it sets is a least one
  // beside that rather than more room under the lift: two cells set
  // `height: 80px` with text of two sizes in them are a row 80px tall, where
  // the lift on top of the height made it 104px.
  //
  // A cell spanning rows asks its first row for its baseline and nothing
  // under it, and the rows it spans for its content and height alone, as
  // Chrome sizes it (Blink's `RowBaselineTabulator` gives it an ascent and
  // no descent): the lifted content hangs out of the cell. 17.5.3 asks only
  // that the rows encompass the cell, whose box is as tall as its content.
  const { lift, own: ascent } = baselineLifts(cells, rows.length, natural);
  const needs = (i: number): number =>
    cells[i].rowSpan > 1
      ? cells[i].box.height
      : Math.max(cells[i].box.height, lift[i] + natural[i]);
  for (let i = 0; i < cells.length; i += 1) {
    const cell = cells[i];
    const need = cell.rowSpan > 1 ? lift[i] + ascent[i] : needs(i);
    // NaN for a spanning cell with no baseline, which Math.max would keep
    if (need > rowHeight[cell.row]) rowHeight[cell.row] = need;
  }
  for (let r = 0; r < rows.length; r += 1) {
    const specified = resolveOrNull(rows[r].style.height, NaN);
    if (specified !== null) rowHeight[r] = Math.max(rowHeight[r], specified);
  }
  // A row-spanning cell only forces height when the rows it covers do not
  // already provide it — otherwise a `rowspan="3"` cell would make each of
  // its three rows as tall as all of it.
  for (let i = 0; i < cells.length; i += 1) {
    const cell = cells[i];
    if (cell.rowSpan <= 1) continue;
    const last = Math.min(rows.length - 1, cell.row + cell.rowSpan - 1);
    let covered = 0;
    for (let r = cell.row; r <= last; r += 1) covered += rowHeight[r];
    covered += rowSpacing * (last - cell.row);
    const missing = needs(i) - covered;
    if (missing > 0) rowHeight[last] += missing;
  }

  // What the rows come to before any height is shared out to them, the
  // spacing above, below and between them in (`TABLE_CONTENT`)
  let rowsOwn = rowSpacing;
  for (let r = 0; r < rows.length; r += 1) {
    if (rows[r].style.visibility !== 'collapse') {
      rowsOwn += rowHeight[r] + rowSpacing;
    }
  }
  TABLE_CONTENT.set(
    table,
    rowsOwn + table.captionTop + table.captionBottom + table.verticalExtra,
  );

  // A table's own height, within its least and greatest, is a least
  // height: what its rows come short of it goes to them (CSS 2.1 17.5.3,
  // which leaves how to its user agents: `growRows`). So is the height a
  // flex or grid layout gave it, stretched or flexed (`FLEXED_HEIGHT`,
  // `USED_HEIGHT`), which is its wrapper box's, captions and all (CSS
  // Flexbox 1, 4): taken as the table's box alone, a table stretched down
  // its line kept its rows at their content's height, and a cell had
  // nothing for `vertical-align` to centre its content in. That one is its
  // height in place of its own, which the flex layout started from: flexed
  // down a column shorter than a height of its own, it is as short as that,
  // where its rows let it be (Blink: "A table interprets forced block-size
  // as the block-size of its rows", `flex_layout_algorithm.cc`).
  const wanted = resolveOrNull(style.height, table.percentHeightBase);
  const given = givenHeight(table);
  if (rows.length) {
    const extraBox = table.verticalExtra;
    const set =
      wanted === null
        ? 0
        : style.boxSizing === 'border-box'
          ? wanted
          : wanted + extraBox;
    const inner = Number.isFinite(given)
      ? given - table.captionTop - table.captionBottom
      : clampHeight(table, set) - extraBox;
    let total = 0;
    for (const h of rowHeight) total += h;
    const extra = inner - total - rowSpacing * (rows.length + 1);
    if (extra > 0) growRows(rowHeight, rowSizing(rows, cells), extra, inner);
  }

  // And a row it takes out has sized the columns with the rest, and is as
  // tall as nothing, with no spacing after it; its cells inherit the value,
  // and are not drawn.
  const rowGone: boolean[] = new Array<boolean>(rows.length);
  for (let r = 0; r < rows.length; r += 1) {
    rowTop[r] = y;
    rowGone[r] = rows[r].style.visibility === 'collapse';
    if (rowGone[r]) rowHeight[r] = 0;
    else y += rowHeight[r] + rowSpacing;
  }

  for (let i = 0; i < cells.length; i += 1) {
    const cell = cells[i];
    const last = Math.min(rows.length - 1, cell.row + cell.rowSpan - 1);
    let height = 0;
    let clip = false;
    for (let r = cell.row; r <= last; r += 1) {
      height += rowHeight[r];
      if (r > cell.row && rowGone[r]) clip = true;
    }
    height += rowSpacing * (last - cell.row);
    if (clip) {
      // down to the last of its rows left in the table, whose spacing went
      // with the rows taken out
      let bottom = rowTop[cell.row] + rowHeight[cell.row];
      for (let r = cell.row + 1; r <= last; r += 1) {
        if (!rowGone[r]) bottom = rowTop[r] + rowHeight[r];
      }
      height = bottom - rowTop[cell.row];
    }
    let width = spannedWidth(widths, cell, spacing);
    // Where its columns are: a cell spanning a column taken out is laid out
    // across all of them, moved left by the width of the ones before the
    // first left in, and clipped to the ones left, which cuts out what was
    // in those (CSS 2.1 17.5.5). The spacing after them goes from the end
    // of its content, which does not line up with the columns it spans.
    // One wholly in them is not drawn.
    let placeX = columnX[cell.column];
    let boxX = placeX;
    if (anyGone) {
      const lastColumn = Math.min(
        columnCount - 1,
        cell.column + cell.colSpan - 1,
      );
      let first = -1;
      let end = -1;
      let before = 0;
      let some = false;
      for (let c = cell.column; c <= lastColumn; c += 1) {
        if (!gone[c]) {
          if (first < 0) first = c;
          end = c;
        } else {
          if (first < 0) before += (some ? spacing : 0) + widths[c];
          some = true;
        }
      }
      if (first < 0) COLLAPSED_CELLS.add(cell.box);
      else if (some) {
        clip = true;
        boxX = columnX[first];
        placeX = boxX - before;
        width = columnX[end] + widths[end] - boxX;
      }
    }
    const inner = cell.box.height;
    // `vertical-align` inside a cell moves the *content*, not the box: the
    // box fills the row, background and all, and the content sits top,
    // middle, bottom or on the row's baseline in it — in the box a height
    // of its own makes too, which is no content to be moved. The cell was
    // laid out above, in this pass over the cells, so this is the one move
    // its content and its static positions get (`moveContent`)
    let offset = lift[i];
    const va = cell.box.style.verticalAlign;
    const content = natural[i];
    const room = Math.max(height, inner);
    if (va === 'middle') offset = Math.max(0, (room - content) / 2);
    else if (va === 'bottom') offset = Math.max(0, room - content);
    moveTo(cell.box, placeX, rowTop[cell.row]);
    moveContent(cell.box, offset);
    cell.box.x = boxX;
    cell.box.width = width;
    if (clip) {
      cell.box.height = height;
      CLIPPED_CELLS.add(cell.box);
    } else {
      cell.box.height = Math.max(inner, height);
    }
  }

  // where the grid lines fell, for the collapsed borders drawn along them
  const collapsed = table.collapsed;
  if (collapsed && collapsed.columns === columnCount) {
    const last = columnCount - 1;
    collapsed.lineX = columnX.map((cx) => cx - table.x);
    collapsed.lineX.push(columnX[last] + widths[last] - table.x);
    collapsed.lineY = rowTop.map((ry) => ry - table.y);
    const bottom = rows.length - 1;
    collapsed.lineY.push(rowTop[bottom] + rowHeight[bottom] - table.y);
  }

  // A row, and a group of them, spans the columns: from the first one's
  // left edge to the last one's right, the spacing around them outside it
  // (CSS 2.1 17.5.1), as it is above and below.
  const gridX = table.contentX + spacing;
  const gridWidth = Math.max(0, x - spacing - gridX);
  for (let r = 0; r < rows.length; r += 1) {
    const row = rows[r];
    row.x = gridX;
    row.y = rowTop[r];
    row.width = gridWidth;
    row.height = rowHeight[r];
  }
  for (const child of table.children) {
    if (child.kind !== 'table-row-group') continue;
    const groupRows = child.children.filter((row) => row.kind === 'table-row');
    if (!groupRows.length) continue;
    child.x = gridX;
    child.y = groupRows[0].y;
    child.width = gridWidth;
    child.height =
      groupRows[groupRows.length - 1].y +
      groupRows[groupRows.length - 1].height -
      child.y;
  }

  return y - top;
}

/**
 * A table's height as its rows and captions came to in its last layout,
 * border box, apart from a height it sets or is given: the least it can be
 * at the width it was laid out at. What a flex layout holds a table item to
 * down a column (`flex.ts`'s `autoMinimums`).
 */
export const TABLE_CONTENT = new WeakMap<Box, number>();

/** The content height a flex or grid layout gave a table, its captions in
 *  (`FLEXED_HEIGHT`, `USED_HEIGHT`), and else NaN. */
export function givenHeight(table: Box): number {
  return FLEXED_HEIGHT.get(table) ?? USED_HEIGHT.get(table) ?? NaN;
}

/** Whether `visibility: collapse` takes a column out: its own, or the
 *  column group's that holds it with no column box of its own. */
function collapsedColumn(column: Box | null, group: Box | null): boolean {
  return (column ?? group)?.style.visibility === 'collapse';
}

/**
 * A table's captions, which are outside the table box (CSS 2.1 17.4): as
 * wide as its border box, the ones on top above its border, and the ones
 * at the bottom laid out here and placed below it by `finishCaptions`,
 * once the table's height is known.
 */
function layoutCaptions(captions: Box[], ctx: LayoutContext, table: Box): void {
  let y = table.y;
  for (const caption of captions) {
    // laid out at the offset its margins give it across the table, which
    // is where it stays across
    layoutBlockIn(caption, ctx, table.width);
    const height = caption.marginTop + caption.height + caption.marginBottom;
    if (caption.style.captionSide === 'bottom') {
      table.captionBottom += height;
      continue;
    }
    moveTo(caption, table.x + caption.x, y + caption.marginTop);
    y += height;
    table.captionTop += height;
  }
}

/** The narrowest the widest caption can be, margins in: its own width
 *  where it has one, and its longest word where it has not. */
function captionMinimum(captions: Box[], ctx: LayoutContext): number {
  let widest = 0;
  for (const caption of captions) {
    let width = measureIntrinsicWidth(caption, ctx, MIN_CONTENT_PROBE);
    // and as wide as a length its own `width` sets: the probe lays it out
    // at none, so an empty caption set to 100px measured nothing, and the
    // table under it was as narrow as its cells
    const set = caption.style.width;
    if (set !== AUTO && !isPct(set)) {
      const length = resolveOrNull(set, 0);
      if (length !== null) {
        const extra =
          caption.style.boxSizing === 'border-box'
            ? 0
            : caption.horizontalExtra;
        width = Math.max(width, length + extra);
      }
    }
    widest = Math.max(widest, width + caption.marginLeft + caption.marginRight);
  }
  return widest;
}

/** The table box has its height: the captions go around it, the bottom
 *  ones below it, and the box grows to hold them. */
export function finishCaptions(table: Box): void {
  if (!table.captionTop && !table.captionBottom) return;
  let y = table.y + table.captionTop + table.height;
  for (const caption of table.children) {
    if (caption.kind !== 'table-caption') continue;
    if (caption.style.captionSide !== 'bottom') continue;
    moveTo(caption, table.x + caption.x, y + caption.marginTop);
    y += caption.marginTop + caption.height + caption.marginBottom;
  }
  table.height += table.captionTop + table.captionBottom;
}

function spannedWidth(widths: number[], cell: Cell, spacing: number): number {
  let width = 0;
  const last = Math.min(widths.length - 1, cell.column + cell.colSpan - 1);
  for (let c = cell.column; c <= last; c += 1) width += widths[c];
  return width + spacing * (last - cell.column);
}

/**
 * `table-layout: fixed`: the columns and the first row decide, and the rest
 * of the table is not measured at all, which is the whole point of it (CSS
 * 2.1 17.5.2.1). A column with a `width` sets its own; failing that, a cell
 * of the first row with one sets the columns it spans, by its border box and
 * less the spacing between them; the columns left share what remains, and
 * where nothing remains, what is left of a table wider than its columns is
 * shared among all of them.
 */
function fixedColumns(
  cells: Cell[],
  columnWidths: (number | null)[],
  columnCount: number,
  available: number,
  spacing: number,
): number[] {
  const widths: number[] = new Array<number>(columnCount).fill(0);
  const set: boolean[] = new Array<boolean>(columnCount).fill(false);
  for (let c = 0; c < columnCount; c += 1) {
    const px = columnWidths[c];
    if (px === null) continue;
    widths[c] = px;
    set[c] = true;
  }
  for (const cell of cells) {
    if (cell.row > 0) break;
    const px = ownWidth(cell.box.style, available);
    if (px === null) continue;
    const box = cell.box;
    // A length within a length `max-width`, which a `min-width` raises
    // and does nothing else to: a fixed table does not measure its cells'
    // content, so a least width has nothing to hold up (CSS Tables 3,
    // 3.8.2 and 3.8.3, as Blink reads them). A percentage is held by a
    // percentage limit only (`ownWidth`). Unheld, a cell `width: 300px;
    // max-width: 100px` took 300 of the table.
    const outer = isPct(box.style.width)
      ? outerWidth(box, px)
      : Math.min(outerWidth(box, px), cellLimits(box).cap);
    const last = Math.min(columnCount, cell.column + cell.colSpan);
    let taken = spacing * (last - cell.column - 1);
    let open = 0;
    for (let c = cell.column; c < last; c += 1) {
      if (set[c]) taken += widths[c];
      else open += 1;
    }
    if (!open) continue;
    const each = Math.max(0, outer - taken) / open;
    for (let c = cell.column; c < last; c += 1) {
      if (set[c]) continue;
      widths[c] = each;
      set[c] = true;
    }
  }
  let used = 0;
  let unset = 0;
  for (let c = 0; c < columnCount; c += 1) {
    if (set[c]) used += widths[c];
    else unset += 1;
  }
  const remaining = Math.max(0, available - used);
  if (unset) {
    for (let c = 0; c < columnCount; c += 1) {
      if (!set[c]) widths[c] = remaining / unset;
    }
  } else if (remaining > 0 && columnCount) {
    for (let c = 0; c < columnCount; c += 1) {
      widths[c] +=
        used > 0 ? (widths[c] / used) * remaining : remaining / columnCount;
    }
  }
  return widths;
}

/**
 * The auto algorithm: measure every cell's max-content and min-content
 * width, then distribute.
 *
 * The distribution is the part worth stating. When the max-content widths
 * fit, they are used — a small table is exactly as wide as its contents.
 * When they do not, the surplus over each column's minimum is scaled down in
 * proportion, so a column of long prose gives up more than a column of
 * dates. A column with an explicit `width` is honoured before either.
 *
 * What a cell asks is its content within its length limits (CSS Tables 3,
 * 3.8.2): its outer min-content width is `max(min-width, min-content)`
 * and its outer max-content width `max(min-width, min-content,
 * min(max-width, max-content))`. A `max-width` caps the min-content too,
 * as Blink has it where the draft does not (`CreateCellInlineConstraint`),
 * so that `td { max-width: 50px }` over a long word, or a line that does
 * not wrap and ends in an ellipsis, makes a column 50 wide and not the
 * word's. Neither limit sets the column's width, which only a `width`
 * does: a cell `min-width: 100px` over 10px of content in a table of 600
 * takes its share of the rest, as one 100 wide would.
 */
function autoColumns(
  cells: Cell[],
  columnWidths: (number | null)[],
  columnLeast: (number | null)[],
  columnCount: number,
  available: number,
  ctx: LayoutContext,
  containingWidth: number,
  fill: boolean,
  spacing: number,
): number[] {
  const max: number[] = new Array<number>(columnCount).fill(0);
  const min: number[] = new Array<number>(columnCount).fill(0);
  const explicit: (number | null)[] = new Array<number | null>(
    columnCount,
  ).fill(null);
  const spanning: Cell[] = [];
  // each cell's outer min-content and max-content, within its limits
  const asks = new Map<Cell, { min: number; max: number }>();

  for (const cell of cells) {
    // Two probe layouts per cell: unconstrained for max-content, and at no
    // width for min-content (`MIN_CONTENT_PROBE`) — which the line breaker
    // answers by breaking at every opportunity, so the widest line is the
    // longest unbreakable word.
    //
    // Cached on the box, because intrinsic widths are width-independent by
    // definition — measuring them per layout pass made a *resize* of a
    // 500-row table cost as much as its first layout (223ms of re-probing
    // measured against 10ms with the cache). The cache's invalidation rule
    // is the box's lifetime: any DOM or style change rebuilds the tree.
    if (cell.box.intrinsicMaxContent < 0) {
      cell.box.intrinsicMaxContent = measureIntrinsicWidth(
        cell.box,
        ctx,
        Infinity,
      );
      // where its words say it exactly, read from the layout just made
      cell.box.intrinsicMinContent =
        (ctx.fonts && exactMinContent(cell.box, ctx.fonts)) ??
        measureIntrinsicWidth(cell.box, ctx, MIN_CONTENT_PROBE, true);
    }
    const { floor, cap } = cellLimits(cell.box);
    const low = Math.min(Math.max(cell.box.intrinsicMinContent, floor), cap);
    const ask = {
      min: low,
      max: Math.max(low, Math.min(cell.box.intrinsicMaxContent, cap)),
    };
    asks.set(cell, ask);
    if (cell.colSpan > 1) {
      spanning.push(cell);
      continue;
    }
    max[cell.column] = Math.max(max[cell.column], ask.max);
    min[cell.column] = Math.max(min[cell.column], ask.min);
    const width = cellWidth(cell, containingWidth);
    if (width !== null) {
      explicit[cell.column] = Math.max(explicit[cell.column] ?? 0, width);
    }
  }

  // a column's own width counts as its cells' do: at least that, and its
  // content's max where that is wider (CSS 2.1 17.5.2.2, step 2); and its
  // `min-width` alone is the least it and its content are, as a cell's
  // is, and sets no width (CSS Tables 3, 3.8.2)
  for (let c = 0; c < columnCount; c += 1) {
    const own = columnWidths[c];
    if (own !== null) explicit[c] = Math.max(explicit[c] ?? 0, own);
    const floor = columnLeast[c];
    if (floor !== null) {
      min[c] = Math.max(min[c], floor);
      max[c] = Math.max(max[c], floor);
    }
  }

  // A spanning cell comes after the cells of one column, the narrower
  // spans first, and adds to its columns only what they come short of it
  // (CSS 2.1 17.5.2.2, step 3). It holds the spacing between them too,
  // room the columns need not find. What it adds goes to those of them
  // with no width set, in proportion to their content, and evenly where
  // they have none. Taken in document order and spread evenly, a spanning
  // cell in a first row was shared out before the cells of one column
  // under it were seen, and a column one of them set to 5px took half.
  spanning.sort((a, b) => a.colSpan - b.colSpan);
  const grow = (into: number[], want: number, cell: Cell): void => {
    const last = Math.min(columnCount - 1, cell.column + cell.colSpan - 1);
    let have = spacing * (last - cell.column);
    for (let c = cell.column; c <= last; c += 1) have += into[c];
    if (!(want > have)) return;
    let free = false;
    for (let c = cell.column; c <= last && !free; c += 1) {
      free = explicit[c] === null;
    }
    let weight = 0;
    let count = 0;
    for (let c = cell.column; c <= last; c += 1) {
      if (free && explicit[c] !== null) continue;
      weight += max[c];
      count += 1;
    }
    for (let c = cell.column; c <= last; c += 1) {
      if (free && explicit[c] !== null) continue;
      into[c] +=
        weight > 0 ? ((want - have) * max[c]) / weight : (want - have) / count;
    }
  };

  // what the columns' content alone asks, before their set widths: the
  // least a column gives way to when the table has less room than its
  // cells' widths want, as beside a float
  const least = min.slice();
  for (const cell of spanning) grow(least, asks.get(cell)!.min, cell);
  for (let c = 0; c < columnCount; c += 1) {
    if (explicit[c] !== null) {
      max[c] = Math.max(min[c], explicit[c] as number);
      min[c] = Math.max(min[c], Math.min(explicit[c] as number, max[c]));
    }
  }
  // and with them: a spanning cell's own width is the least it is, as a
  // single cell's is (step 1), so a cell over three columns set to 100px,
  // with 20px between them, has 60 to share, where it had none
  for (const cell of spanning) {
    const own = cellWidth(cell, containingWidth) ?? 0;
    const ask = asks.get(cell)!;
    grow(min, Math.max(ask.min, own), cell);
    grow(max, Math.max(ask.max, own), cell);
  }
  for (let c = 0; c < columnCount; c += 1) min[c] = Math.min(min[c], max[c]);

  const totalMax = max.reduce((a, b) => a + b, 0);
  if (totalMax <= available) {
    // Everything fits. A table with a width of its own still fills it (CSS
    // 2.1 17.5.2.2): the columns not set to a width take the rest in
    // proportion to what they asked for, or every column does where all are
    // set. Returned as asked, `<table width="600">` drew its cells at their
    // content's width and left the rest of its 600 empty.
    if (!fill || available <= totalMax) return max;
    const set = explicit.every((w) => w !== null);
    let weight = 0;
    let count = 0;
    for (let c = 0; c < columnCount; c += 1) {
      if (!set && explicit[c] !== null) continue;
      weight += max[c];
      count += 1;
    }
    const extra = available - totalMax;
    return max.map((m, c) =>
      !set && explicit[c] !== null
        ? m
        : m + (weight > 0 ? (extra * m) / weight : extra / count),
    );
  }
  const totalMin = min.reduce((a, b) => a + b, 0);
  if (totalMin >= available) {
    // Less room than the cells' widths want: a width a cell was set to
    // gives way first, down to what its content asks, and a table never
    // goes narrower than its words (CSS 2.1 17.5.2.2), which it overflows.
    const totalLeast = least.reduce((a, b) => a + b, 0);
    if (totalLeast >= available) return least;
    const give = totalMin - totalLeast;
    return min.map(
      (m, c) => m - ((m - least[c]) / give) * (totalMin - available),
    );
  }
  const slack = available - totalMin;
  const surplus = totalMax - totalMin;
  return max.map((m, c) => min[c] + ((m - min[c]) / surplus) * slack);
}

/**
 * The width each column is set to, or null, from the `<col>` and the
 * `<colgroup>` it is in. A group is its columns' default and no more: the
 * width specified for a column is its column's, or else its group's (CSS
 * Tables 3, 3.8.3), so a `<col>` with a width of its own keeps it however
 * wide the group is, and one with none takes the group's whole, not a
 * share of it. A group with no `<col>` stands for each column it spans
 * (`<colgroup span>`), and each is as wide as the group says. That is
 * HTML 4's "a default width for each column" and Blink's
 * (`ColumnConstraintsBuilder`), where CSS 2.1 17.5.2.2 spread a group's
 * width over its columns wherever theirs came to less: a group of 100
 * over two columns of 20 made each 50, and over two of none made each 50,
 * where Chrome has 20 and 100.
 *
 * Only a length is a default, raised to the group's `min-width` and the
 * `<col>`'s, and only in an auto table, as Blink has it: a fixed table
 * takes no group's width for a `<col>`, and its columns share the table as
 * though the group set none. A `<col>` with a percentage keeps it.
 */
function columnWidths(
  columnBoxes: (Box | null)[],
  columnGroups: (Box | null)[],
  base: number,
  fixed: boolean,
): (number | null)[] {
  return columnBoxes.map((column, c) => {
    const group = columnGroups[c];
    if (!column) return group ? partWidth(group, base) : null;
    const own = partWidth(column, base);
    if (own !== null || fixed || !group || isPct(group.style.width)) return own;
    const width = partWidth(group, base);
    return width === null ? null : Math.max(width, partLeast(column) ?? 0);
  });
}

/** The least each column is, where a `min-width` says (`partLeast`): its
 *  `<col>`'s, or, where it has none, the group it is in. A group's
 *  `min-width` does not reach the `<col>`s in it, as in Blink, which makes
 *  a group's limits a column's only where the group stands for it:
 *  `<colgroup style="min-width:100px">` over two `<col>`s of 10px content
 *  is 20 wide, where the 100 was spread over them. */
function columnLeast(
  columnBoxes: (Box | null)[],
  columnGroups: (Box | null)[],
): (number | null)[] {
  return columnBoxes.map((column, c) => {
    const part = column ?? columnGroups[c];
    return part ? partLeast(part) : null;
  });
}

/** A column's or a column group's width, or null where it sets none: its
 *  `width`, raised to a length `min-width`. A `max-width` does nothing to
 *  it. CSS Tables 3, 3.8.2 makes a column's outer min-content width
 *  `max(min-width, width)`, which is at least as wide as any `max-width`
 *  could hold it to, and Blink reads no `max-width` on a column at all
 *  (`CreateColumn`): `<col style="width:100px; max-width:50px">` is 100
 *  wide, where it was 50. A percentage `max-width` holds a percentage
 *  `width` (`ownWidth`), and a percentage `min-width` is ignored. */
function partWidth(box: Box, base: number): number | null {
  const width = ownWidth(box.style, base);
  if (width === null) return null;
  return Math.max(0, width, partLeast(box) ?? 0);
}

/** The least a column or a column group is, where a length `min-width`
 *  says: what its cells ask is held up to it, and it sets no width of its
 *  own, which a fixed table's columns have nothing but (`fixedColumns`).
 *  Read as a width, `<col style="min-width:100px">` held a column of
 *  prose to 100 in an auto table, where it is as wide as the prose is. */
function partLeast(box: Box): number | null {
  const min = box.style.minWidth;
  return typeof min === 'number' && min > 0 ? min : null;
}

/** A cell's own `width`, its padding and borders in, or null. A
 *  percentage is a share of the table its padding and borders are part
 *  of, as browsers read it: added on, a 90% cell and a 10% one came to
 *  more than the table, which then took it back from both. A length is
 *  held within a length `max-width`, which CSS 2.1 leaves undefined and
 *  every browser does: a cell set `width: 3in; max-width: 1in` is an inch
 *  wide. A percentage is not: `width: 50%; max-width: 100px` is half the
 *  table, as in Blink, which keeps a percentage apart from the lengths
 *  that cap what a cell's content asks (`autoColumns`). A `min-width`
 *  sets no width, and holds up what the cell asks instead.
 *
 *  A percentage `max-width` holds a percentage `width` and nothing else
 *  (CSS Tables 3, 3.8.2, and `ownWidth`): a cell `width: 100px;
 *  max-width: 10%` in a table of 600 is 100 wide, where it was 60. */
function cellWidth(cell: Cell, base: number): number | null {
  const box = cell.box;
  const width = ownWidth(box.style, base);
  if (width === null) return null;
  if (isPct(box.style.width)) return Math.max(width, box.horizontalExtra);
  return Math.min(outerWidth(box, width), cellLimits(box).cap);
}

/** A cell's length `min-width` and `max-width` as border-box widths, the
 *  limit raised to the least, or 0 and Infinity where it has none: what
 *  its column sizes its content within (`autoColumns`), and a fixed table
 *  its width (`fixedColumns`). As Blink's `InlineSizesFromStyle`. */
function cellLimits(box: Box): { floor: number; cap: number } {
  const { minWidth, maxWidth } = box.style;
  const floor = typeof minWidth === 'number' ? outerWidth(box, minWidth) : 0;
  const cap =
    typeof maxWidth === 'number'
      ? Math.max(outerWidth(box, maxWidth), floor)
      : Infinity;
  return { floor, cap };
}

/** A width a cell's style gives, as its border box. */
function outerWidth(box: Box, width: number): number {
  return box.style.boxSizing === 'border-box'
    ? Math.max(width, box.horizontalExtra)
    : width + box.horizontalExtra;
}

/** A cell's, a column's or a column group's `width` as the columns read
 *  it, or null: a percentage no more than a percentage its `max-width` is
 *  — the percentage each contributes is `min(percentage width, percentage
 *  max-width)`, a `max-width` that is no percentage counting as an
 *  infinite one (CSS Tables 3, 3.8.2). */
function ownWidth(style: ComputedStyle, base: number): number | null {
  const width = tableWidth(style.width, base);
  const limit = style.maxWidth;
  if (width === null || !isPct(style.width)) return width;
  if (limit === 'none' || !isPct(limit) || limit.px || limit.of) return width;
  return Math.min(width, lengthAgainst(limit, base) ?? width);
}

/** A cell's or a column's width. One that adds a percentage to a length,
 *  a `calc()`, is `auto` in a table, as browsers read it: a column cannot be
 *  both a share of the table and a size of its own. */
function tableWidth(len: Len, base: number): number | null {
  if (isPct(len) && (len.px || len.of)) return null;
  return lengthAgainst(len, base);
}

function lengthAgainst(len: Len, base: number): number | null {
  if (len === AUTO) return null;
  return resolveOrNull(len, base);
}

/**
 * How far each cell's content moves down to put its baseline on its first
 * row's: 0 for a cell aligned `top`, `middle` or `bottom`, which is placed
 * once the row's height is known. A cell's baseline is its first line box's,
 * at any depth, or the bottom of its content where it has none (CSS 2.1
 * 17.5.3); it is taken as laid out, from the cell's top. That bottom is of
 * the content (`natural`) and not of a height the cell sets, which "does not
 * increase the height of the cell box": taken from the set height, a cell
 * holding one block of 30px in 80px hung the text beside it from 80px. An
 * empty cell has nothing to align and says nothing about the row's, as in a
 * browser. `own` is each cell's baseline from its top, NaN where it has none
 * to give.
 */
function baselineLifts(
  cells: Cell[],
  rowCount: number,
  natural: number[],
): { lift: number[]; own: number[] } {
  const lift = new Array<number>(cells.length).fill(0);
  const own = new Array<number>(cells.length).fill(NaN);
  let any = false;
  for (const cell of cells) {
    const va = cell.box.style.verticalAlign;
    if (va !== 'top' && va !== 'middle' && va !== 'bottom') any = true;
  }
  if (!any) return { lift, own };
  const row = new Array<number>(rowCount).fill(-Infinity);
  for (let i = 0; i < cells.length; i += 1) {
    const box = cells[i].box;
    const va = box.style.verticalAlign;
    if (va === 'top' || va === 'middle' || va === 'bottom') continue;
    const first = firstBaselineIn(box);
    if (first === null && !holdsFlow(box)) continue;
    own[i] =
      first !== null
        ? first - box.y
        : natural[i] - box.padBottom - box.borderBottom;
    row[cells[i].row] = Math.max(row[cells[i].row], own[i]);
  }
  for (let i = 0; i < cells.length; i += 1) {
    if (own[i] === own[i]) lift[i] = row[cells[i].row] - own[i];
  }
  return { lift, own };
}

/** Whether a cell has anything in flow in it. */
function holdsFlow(box: Box): boolean {
  for (const child of box.children) {
    if (child.outOfFlow || child.isFloat) continue;
    if (child.kind === 'text' && isBlank(child.text)) continue;
    return true;
  }
  return false;
}

/** What a row's height is set as: a length its own or a cell's in it
 *  sets, which makes it constrained, and a percentage one does. */
interface RowSizing {
  constrained: boolean;
  percent: number | null;
}

function rowSizing(rows: Box[], cells: Cell[]): RowSizing[] {
  const sizing = rows.map((row): RowSizing => {
    const height = row.style.height;
    return {
      constrained: typeof height === 'number',
      percent: height !== AUTO && isPct(height) ? height.pct : null,
    };
  });
  for (const cell of cells) {
    if (cell.rowSpan > 1 || !sizing[cell.row]) continue;
    const height = cell.box.style.height;
    const row = sizing[cell.row];
    if (typeof height === 'number') row.constrained = true;
    else if (height !== AUTO && isPct(height)) {
      row.percent = Math.max(row.percent ?? 0, height.pct);
    }
  }
  return sizing;
}

/**
 * The height a table has past its rows' given out among them, as browsers
 * give it (the CSS Tables 3 draft leaves it open, csswg-drafts#4418): first
 * to the rows a percentage sets, up to it; then to the rows nothing sets
 * that have content, in proportion to their heights; then, where every row
 * with content is set, to the empty rows, those nothing sets first, evenly;
 * and else to every row with content, in proportion. A row whose cells set
 * its height keeps it while an empty row beside it takes the rest.
 */
function growRows(
  heights: number[],
  sizing: RowSizing[],
  extra: number,
  base: number,
): void {
  const n = heights.length;
  const deficit = heights.map((h, r) => {
    const pct = sizing[r].percent;
    return pct ? Math.max(0, (pct / 100) * base - h) : 0;
  });
  const empty: number[] = [];
  const nothingSetEmpty: number[] = [];
  const full: number[] = [];
  const nothingSetFull: number[] = [];
  let setFull = 0;
  for (let r = 0; r < n; r += 1) {
    const set = sizing[r].constrained || sizing[r].percent !== null;
    if (heights[r] === 0 && deficit[r] === 0) {
      empty.push(r);
      if (!set) nothingSetEmpty.push(r);
    } else {
      full.push(r);
      if (set) setFull += 1;
      else nothingSetFull.push(r);
    }
  }
  const owed = deficit.reduce((a, b) => a + b, 0);
  if (owed > 0) {
    const give = Math.min(owed, extra);
    for (let r = 0; r < n; r += 1) heights[r] += (give * deficit[r]) / owed;
    extra -= give;
    if (!(extra > 0)) return;
  }
  const grow = (which: number[], even: boolean) => {
    let sum = 0;
    for (const r of which) sum += heights[r];
    for (const r of which) {
      heights[r] +=
        even || !(sum > 0) ? extra / which.length : (extra * heights[r]) / sum;
    }
  };
  if (nothingSetFull.length) grow(nothingSetFull, false);
  else if (empty.length && empty.length + setFull === n) {
    grow(nothingSetEmpty.length ? nothingSetEmpty : empty, true);
  } else grow(full, false);
}
